    "passage": "The exact origins of human language remain a major question for evolutionary biologists. Unique to human language ______ to flexibly recombine a limited sound set into words and sequences, generating an endless series of new sentences. In contrast, the production of these types of sequences in other animals appears limited, stunting their ability to create meaning.",
