    "difficulty": "Medium",
    "difficultyStatus": "provisional",
    "passage": "A novel method of air conditioning—which has been adopted by some of the world's most powerful corporations, uses the simple power of ice. The system works ______ when lower power usage means that energy is cheaper and lower temperatures require less power to freeze water.",
