    "passage": "Unlike electronic devices, which are powered by the manipulation of electrons, the human brain relies on the movement of ions in liquid. Inspired by this process, researchers have long sought to develop water-based \"ionics\". Although ions in water move more slowly than the electrons that are used in smartphones or ______ researchers believe that the ionic species with different physical and chemical properties could be harnessed in a variety of ways.",
