    "skill": "Form, Structure, and Sense",
    "difficulty": "Medium",
    "difficultyStatus": "provisional",
    "passage": "For several weeks each year, more than 200 artists from 60 countries gather in Santa Fe to offer handmade masterworks. Every July, one of the world's largest folk-art festivals ______ together artists from every corner of the globe for a vast and colorful international bazaar.",
    "question": "Which choice completes the text so that it conforms to the conventions of Standard English?",
    "options": [
      "A. brings",
      "B. bring",
      "C. have brought",
      "D. bringing"
    ],
