    "skill": "Form, Structure, and Sense",
    "difficulty": "Easy",
    "difficultyStatus": "provisional",
    "passage": "Haiku poems, which contain just 17 syllables, can describe any person or object, but they are seldom complicated or difficult to understand. Each Haiku must contain a kigo, a season word that indicates what time of the year the Haiku is set. For example, blossoms would indicate ______",
