    "skill": "Form, Structure, and Sense",
    "difficulty": "Easy",
    "difficultyStatus": "provisional",
    "passage": "Most jurors are not compensated at rates sufficient to replace lost wages. As a result, many citizens called for jury duty seek to avoid selection by demonstrating that ______ have urgent commitments or would experience financial hardship.",
    "question": "Which choice completes the text so that it conforms to the conventions of Standard English?",
    "options": [
      "A. he or she",
      "B. they",
      "C. one",
      "D. you"
    ],
    "answer": "B",
    "explanation": "The four choices are four different pronouns: A \"he or she\", B \"they\", C \"one\", D \"you\". The sentence around them decides which one is possible. Identify what noun the pronoun is replacing (its antecedent). The pronoun must match that noun's number and clearly refer to it. It / he / she / its are singular. They / them / their are plural. Ask: \"What noun is this pronoun replacing in the action?\" Is that noun singular or plural? Match the pronoun to THAT noun's number, not the closest noun. The answer is B, \"they\".",
