    "skill": "Boundaries",
    "difficulty": "Hard",
    "difficultyStatus": "provisional",
    "passage": "Recent research suggests that short-term training in self-regulation—the ability to manage attention, emotion, and impulses, as well as to persevere in achieving ______ have long-term effects for children. A recent study found that children who participated in a single unit on self-regulation were still experiencing positive effects more than three years later.",
    "question": "Which choice completes the text so that it conforms to the conventions of Standard English?",
    "options": [
      "A. goals, can",
      "B. goals can",
      "C. goals—can",
      "D. goals can:"
    ],
    "answer": "C",
    "explanation": "The four choices are the same words. They differ only in what comes after \"goals\": A a comma, B nothing, C a dash, D nothing. A pair of dashes / parens / commas surrounds nonessential information. A single dash (like a single colon) can also introduce an explanation. The opening and closing marks must match. Ask: If I remove the text between the marks, does the sentence still work? If yes, paired punctuation is needed. The opening and closing marks MUST match. The answer is C, \"goals—can\".",
    "strategy": "Run-On Radar",
    "ruleType": "Dash",
