    "id": "a5945508",
    "skill": "Form, Structure, and Sense",
    "difficulty": "Medium",
    "difficultyStatus": "provisional",
    "passage": "In the winter of 1885, archaeologists in Greece discovered a unique assembly of figures. Buried in 480 BC, they had been spared 2,500 years of vandalism. Researchers were astonished—not only because of the importance of the works, but also because of the excellent preservation of ______ original surface paint.",
    "question": "Which choice completes the text so that it conforms to the conventions of Standard English?",
    "options": [
      "A. their",
      "B. its",
      "C. his or her",
      "D. one's"
    ],
    "answer": "A",
    "explanation": "The four choices are four different pronouns: A \"their\", B \"its\", C \"his or her\", D \"one's\". The sentence around them decides which one is possible. Identify what noun the pronoun is replacing (its antecedent). The pronoun must match that noun's number and clearly refer to it. It / he / she / its are singular. They / them / their are plural. Ask: \"What noun is this pronoun replacing in the action?\" Is that noun singular or plural? Match the pronoun to THAT noun's number, not the closest noun. The answer is A, \"their\".",
