    "passage": "While bees can survive in the dark, they prefer to be in the sunlight. The shaded interiors of woodlands are therefore considered a poor habitat for bees. New research shows that many types of bees are active high above the ______ suggests wild bees are just as happy in treetops as they are among the flowers at ground level.",
