    "passage": "Nicknamed Iron Riders, the Buffalo Soldiers volunteer bicycle corps departed from Fort Missoula, Montana, on June 14, 1897, embarking on a 1,900-mile journey to St. Louis. During their 41-day journey, which made headlines around the United States, ______ snow, sleet, hail, heavy rain, and oppressive heat.",
